## ✅ 8. Sortable Table (With JavaScript)

```html
<table id="sortableTable">
  <thead>
    <tr>
      <th onclick="sortTable(0)">Item</th>
      <th onclick="sortTable(1)">Quantity</th>
    </tr>
  </thead>
  <tbody>
    <tr><td>Apples</td><td>12</td></tr>
    <tr><td>Oranges</td><td>5</td></tr>
    <tr><td>Bananas</td><td>9</td></tr>
  </tbody>
</table>

<script>
function sortTable(col) {
  const table = document.getElementById("sortableTable");
  let switching = true;
  let dir = "asc";
  let switchcount = 0;

  while (switching) {
    switching = false;
    const rows = table.rows;

    for (let i = 1; i < (rows.length - 1); i++) {
      let shouldSwitch = false;
      let x = rows[i].getElementsByTagName("TD")[col];
      let y = rows[i + 1].getElementsByTagName("TD")[col];

      if (dir === "asc" && x.innerHTML.toLowerCase() > y.innerHTML.toLowerCase()) {
        shouldSwitch = true;
        break;
      } else if (dir === "desc" && x.innerHTML.toLowerCase() < y.innerHTML.toLowerCase()) {
        shouldSwitch = true;
        break;
      }
    }

    if (shouldSwitch) {
      rows[i].parentNode.insertBefore(rows[i + 1], rows[i]);
      switching = true;
      switchcount++;
    } else {
      if (switchcount === 0 && dir === "asc") {
        dir = "desc";
        switching = true;
      }
    }
  }
}
</script>
```

